import{invalidKeyInput}from"./invalid_key_input.js";import{encode as b64u}from"../util/base64url.js";import{isCryptoKey,isKeyObject}from"./is_key_like.js";export async function keyToJWK(e){if(isKeyObject(e)){if("secret"!==e.type)return e.export({format:"jwk"});e=e.export()}if(e instanceof Uint8Array)return{kty:"oct",k:b64u(e)};if(!isCryptoKey(e))throw new TypeError(invalidKeyInput(e,"CryptoKey","KeyObject","Uint8Array"));if(!e.extractable)throw new TypeError("non-extractable CryptoKey cannot be exported as a JWK");const{ext:t,key_ops:r,alg:o,use:i,...y}=await crypto.subtle.exportKey("jwk",e);return"AKP"===y.kty&&(y.alg=o),y}